// A1Q4 — Q04_DespawnRogueGuards (per-monster iterate callback).
// For each Rogue guard monster (classId 0x92) escorting/blocking near Tristram:
// if it still has an AI sub, clear it (graceful); otherwise force a Death
// lifecycle transition. On kill, marks the quest sub-flag 0x61 (guards cleared).
// Driven by Q04_TimerDespawnRogueGuards.
BOOL __fastcall Q04_DespawnRogueGuards(::SGAMEDATA * pGame, D2UnitStrc * pUnit, void * pArg) {
    D2MonsterAiStrc* pMonsterAi;
    D2MonsterKillStrc sKill;
    if (!pUnit || pUnit->nClassId != 0x92) {
      return 0;
    }
    if (pUnit->eUnitType == UNIT_MONSTER && pUnit->pUnitData.pUnitDataMonster) {
      pMonsterAi = pUnit->pUnitData.pUnitDataMonster->pMonsterAi;
    } else {
      pMonsterAi = 0;
    }

    BOOL bHasAiSub = Monster::MonsterAI::HasAiSub(pMonsterAi);
    if (bHasAiSub) {
      Monster::MonsterAI::ClearAISub(pGame, pUnit, Q04_SendQuestStatePacket, false);
      return 1;
    }

    Monster::MonsterMode::SetCurrentSkill(pUnit, Death, &sKill);
    Monster::MonsterMode::MONSTERAI_ExecuteLifecycleTransition(pGame, &sKill, 1);
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_TheSearchForCain);
    if (!pQuestData) {
      return 1;
    }

    pQuestData->pQuestSpecificData.pA1Q4->sSub.bPortalArmed = '\x01';
    return 1;
}

// A1Q4 — Q04_SpawnDeckardCainNpc: spawns the rescued Deckard Cain NPC unit
// (monster classId 0x109) at/near a given room tile. Validates the requested tile
// is inside the room, then retries FindSpawnableLocation + SpawnMonster up to ~0x14
// nearby rooms until placement succeeds. On success flags Cain init/resurrect, records
// his unit GUID into the quest sub-struct, and sets the "Cain spawned" flag (0x51).
static void __stdcall Q04_SpawnDeckardCainNpc(D2RoomStrc * pRoom, ::SGAMEDATA * pGame, int32_t nX, int32_t nY) {
    D2DrlgRoomCoordsStrc sRoomCoords;
    POINT ptCainSpawnPos;
    D2QuestDataStrc* pQuestData;
    pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_TheSearchForCain);
    if (!pQuestData) {
      return;
    }

    D2QuestDataA1Q1Strc* pA1Q4Specific;
    pA1Q4Specific = pQuestData->pQuestSpecificData.pA1Q1;
    D2RoomStrc* pSpawnRoomOut;
    pSpawnRoomOut = pRoom;
    D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomCoordinates(pRoom, &sRoomCoords);
    int iRetry;
    iRetry = 0;
    ptCainSpawnPos.x = nX;
    ptCainSpawnPos.y = nY;
    do {
      if (ptCainSpawnPos.x >= sRoomCoords.dwXStart && ptCainSpawnPos.y >= sRoomCoords.dwYStart && ptCainSpawnPos.x < sRoomCoords.dwXSize - 1 + sRoomCoords.dwXStart && ptCainSpawnPos.y < sRoomCoords.dwYSize - 1 + sRoomCoords.dwYStart) {
        goto spawn_cain;
      }

      iRetry++;
      ptCainSpawnPos.x++;
      ptCainSpawnPos.y++;
    } while (iRetry <= 0x14);

    ptCainSpawnPos.x = nY;
    spawn_cain:
    FindSpawnableLocation(pRoom, &ptCainSpawnPos, 2, 0x100, &pSpawnRoomOut, 1, 100);
    if (!pSpawnRoomOut) {
      ptCainSpawnPos.x = nX;
      ptCainSpawnPos.y = nY;
      pSpawnRoomOut = pRoom;
    }

    D2UnitStrc* pSpawnedCain;
    pSpawnedCain = Monster::Create::SpawnMonsterAtRoomPos(pGame, pSpawnRoomOut, ptCainSpawnPos.x, ptCainSpawnPos.y, 0x109, eD2MonsterAnimMode_ns::Neutral, 5, 0);
    if (!pSpawnedCain) {
      iRetry = 0;
      do {
        ptCainSpawnPos.y++;
        ptCainSpawnPos.x++;
        pSpawnRoomOut = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pSpawnRoomOut, ptCainSpawnPos.x, ptCainSpawnPos.y);
        if (!pSpawnRoomOut) {
          ptCainSpawnPos.x = nX;
          ptCainSpawnPos.y = nY;
          pSpawnRoomOut = pRoom;
        }

        FindSpawnableLocation(pSpawnRoomOut, &ptCainSpawnPos, 2, 0x100, &pSpawnRoomOut, 2, 100);
        if (!pSpawnRoomOut) {
          ptCainSpawnPos.x = nX;
          ptCainSpawnPos.y = nY;
          pSpawnRoomOut = pRoom;
        }

        iRetry++;
        pSpawnedCain = Monster::Create::SpawnMonsterAtRoomPos(pGame, pSpawnRoomOut, ptCainSpawnPos.x, ptCainSpawnPos.y, 0x109, eD2MonsterAnimMode_ns::Neutral, 10, 0);
        if (pSpawnedCain) {
          goto register_spawned_cain;
        }
      } while (iRetry < 0x14);

      pSpawnedCain = Monster::Create::SpawnMonsterAtRoomPos(pGame, pRoom, nX, nY, 0x109, eD2MonsterAnimMode_ns::Neutral, 0xf, 0);
      if (!pSpawnedCain) {
        return;
      }
    }

    register_spawned_cain:
    pSpawnedCain->eUnitFlags |= UNITFLAG_ISRESURRECT | UNITFLAG_ISINIT;
    *(uint8_t*)((int)pA1Q4Specific->sQuestGUID.aPlayerGUID + 0x51) = 1;
    *(uint8_t*)((int)pA1Q4Specific->sQuestGUID.aPlayerGUID + 0x52) = 0;
    pA1Q4Specific->sQuestGUID.aPlayerGUID[0x1a] = pSpawnedCain->nUnitGUID;
}

// A1Q4 — Q04_MarkCannotComplete (per-player iterate callback).
// If a player has NOT yet Completed and has no RewardAwaits, mark their quest record
// CannotCompleteQuestInGame (they were not present when the quest was force-progressed,
// so they can't finish it this game) and add them to quest list1. Run when the quest
// is advanced past the point a latecomer could legitimately complete it.
BOOL __fastcall Q04_MarkCannotComplete(::SGAMEDATA * pGame, D2UnitStrc * pUnit, void * pArg) {
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    BOOL bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_TheSearchForCain, QUESTSTATE_Completed);
    if (bQuestState) {
      return 0;
    }

    bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_TheSearchForCain, QUESTSTATE_RewardAwaits);
    if (bQuestState) {
      return 0;
    }

    D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_TheSearchForCain, QUESTSTATE_CannotCompleteQuestInGame);
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_TheSearchForCain);
    if (!pUnit) {
      QUESTGUID_AddPlayerToList(&pQuestData->pQuestSpecificData.pA1Q4->sQuestGUID1, -1);
      return 0;
    }

    QUESTGUID_AddPlayerToList(&pQuestData->pQuestSpecificData.pA1Q4->sQuestGUID1, pUnit->nUnitGUID);
    return 0;
}

// A1Q4 — Q04_Callback_14 (quest event handler, slot 0xe): item-count bookkeeping.
// On the relevant event, bumps the quest sub-struct's held-quest-item counter (field
// 0x1f) for each of the deciphered scroll ('bkd ') and Scroll of Inifuss ('bks ')
// the player currently carries. No quest-state transition.
void __fastcall Q04_Callback14_PlayerJoinedGame(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    int* piVar1;
    D2QuestDataA1Q1Strc* pDVar2 = pQuestData->pQuestSpecificData.pA1Q1;
    D2UnitStrc* pDVar3 = ITEMS::Items::Drop::HasQuestItem(pQuestArgs->pGame, pQuestArgs->pPlayer, 0x20646b62);
    D2UnitStrc* pDVar4 = ITEMS::Items::Drop::HasQuestItem(pQuestArgs->pGame, pQuestArgs->pPlayer, 0x20736b62);
    if (pDVar3) {
      piVar1 = pDVar2->sQuestGUID.aPlayerGUID + 0x1f;
      (*piVar1)++;
    }
    if (!pDVar4) {
      return;
    }

    piVar1 = pDVar2->sQuestGUID.aPlayerGUID + 0x1f;
    (*piVar1)++;
}

// A1Q4 — Q04_DeactivateCairnStones: tears down the Cairn Stones puzzle after it has
// served its purpose. If the stones-active flag (0x47) is set, finds the Cairn Stones
// object (classId 0x1e) and stops its animation. Clears the quest's local active byte,
// broadcasts step 1 (Q04_NotifyQuestStateToPlayer), sets step flag 3, clears sub-flag
// 0x58, and re-syncs all players. Called from Callback_06/Callback_09 on completion.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a1q4.cpp
static void __stdcall Q04_DeactivateCairnStones(D2QuestDataStrc * pQuestData) {
    D2QuestDataA1Q4Strc* pQuestSpecific = pQuestData->pQuestSpecificData.pA1Q4;
    if (pQuestSpecific->sSub.bTreeObjectSaved == '\x01') {
      D2UnitStrc* pUnit;
      pUnit = UNIT::SUnit::FindUnitFromTable(pQuestData->pGame, UNIT_OBJECT, pQuestSpecific->sSub.nTreeObjectGUID);
      if (pUnit && pUnit->nClassId == 0x1e) {
        D2Common::Units::SetupUpdateFlag(pUnit, 0);
      }

      pQuestData->nQuestPacketFlags = '\0';
      QUEST_SetStateAndBroadcast(pQuestData, 1, nullptr, (::fpExecuteOnUnitFunction)Q04_NotifyQuestStateToPlayer, true);
      QUEST_SetStateFlag(pQuestData, 3, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a1q4.cpp", 0x397);
      pQuestSpecific->sSub.nStonesUnitGUID = 0;
      UNIT::SUnit::IteratePlayerOrMonsterUnits(pQuestData->pGame, 0, nullptr, (::fpExecuteOnUnitFunction)Q04_SyncQuestStepToPlayer);
      return;
    }

    pQuestData->nQuestPacketFlags = '\0';
    QUEST_SetStateAndBroadcast(pQuestData, 1, nullptr, (::fpExecuteOnUnitFunction)Q04_NotifyQuestStateToPlayer, true);
    QUEST_SetStateFlag(pQuestData, 3, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a1q4.cpp", 0x39f);
    pQuestSpecific->sSub.nStonesUnitGUID = 0;
}

// A1Q4 — Q04_Callback_09 (quest event handler, slot 9): item-drop/loss watcher.
// Hooked while the Scroll-of-Inifuss puzzle is live. When a quest scroll ('bkd '/'bks ')
// leaves the player's inventory, decrements the held-item count; if the count hits 0
// before the puzzle is solved (stones-active flag 0x47 set, not yet solved), it tears
// the puzzle back down via Q04_DeactivateCairnStones and resets step flag to 3.
// @sourcefile d:\diablo2\Diablo2\Source\D2Game/Quests/a1q4.cpp
void __fastcall Q04_Callback09_PlayerDroppedWithQuestItem(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    if (!(pQuestData->bIsNotIntroduction != '\0' && pQuestData->nStateFlag != 6)) {
      return;
    }

    D2QuestDataA1Q4Strc* pA1Q1Data = pQuestData->pQuestSpecificData.pA1Q4;
    uint32_t nItemCode = D2Common::ITEMS::Items::ITEM_GetItemsTxt_szCode(pQuestArgs->pTarget);
    if (nItemCode == 0x20646b62 || nItemCode == 0x20736b62) {
      pA1Q1Data->sSub.nRewardRetryCount--;
    }
    if (!(!pA1Q1Data->sSub.nRewardRetryCount && pQuestData->nStateFlag <= 5 && pA1Q1Data->sSub.field_0x37 != 1 && pA1Q1Data->sSub.bTreeObjectSaved == '\x01')) {
      return;
    }

    QUEST_SetStateFlag(pQuestData, 3, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a1q4.cpp", 0x3f7);
    Q04_DeactivateCairnStones(pQuestData);
}

// A1Q4 — Q04_Callback_10 (quest event handler, slot 10/0xa): per-player cleanup.
// Calls SetRewardAndFinishFlags then removes the player from quest lists 1 and 2.
// Run as the quest wraps up so stale player references are purged.
void __fastcall Q04_Callback10_PlayerLeavesGame(D2QuestDataStrc * pQuestData, D2QuestArgStrc * pQuestArgs) {
    int32_t nPlayerGUID;
    SetRewardAndFinishFlags(pQuestData, pQuestArgs);
    D2QuestDataA1Q4Strc* pDVar1 = pQuestData->pQuestSpecificData.pA1Q4;
    if (!pQuestArgs->pPlayer) {
      nPlayerGUID = -1;
    } else {
      nPlayerGUID = pQuestArgs->pPlayer->nUnitGUID;
    }

    QUESTGUID_RemovePlayerFromList(&pDVar1->sQuestGUID1, nPlayerGUID);
    if (!pQuestArgs->pPlayer) {
      QUESTGUID_RemovePlayerFromList(&pDVar1->sQuestGUID2, -1);
      return;
    }

    QUESTGUID_RemovePlayerFromList(&pDVar1->sQuestGUID2, pQuestArgs->pPlayer->nUnitGUID);
}

// A1Q4 — Q04_SpawnTristramPortal: opens the red Tristram portal at the Cairn Stones.
// Looks up the Cairn Stones unit, reads its tile, and calls SERVER_SpawnPortal to
// LEVEL_Tristram (portal classId 0x3c) offset +4,+4 from the stones. On success sets
// the "portal opened" flag (0x45) and clears the "spawn-pending" flag (0x44).
// Scheduled as a quest timer from Objects_InitFn06.
uint8_t __fastcall Q04_SpawnTristramPortal(::SGAMEDATA * pGame, D2QuestDataStrc * pQuestData) {
    int nStonesY;
    int nStonesX;
    D2RoomStrc* pRoom;
    D2QuestDataA4Q2Strc* pDVar1 = pQuestData->pQuestSpecificData.pA4Q2;
    D2UnitStrc* pUnit = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_OBJECT, pDVar1->nLastPortalObjectMode);
    if (pUnit) {
      eD2UnitType eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        nStonesY = pUnit->pPath.pStaticPath->nPosY;
      } else if (pUnit->pPath.pDynamicPath) {
        nStonesY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
      } else {
        nStonesY = 0;
      }

      eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        nStonesX = pUnit->pPath.pStaticPath->nPosX;
      } else if (pUnit->pPath.pDynamicPath) {
        nStonesX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
      } else {
        nStonesX = 0;
      }

      BOOL bIgnoreSpawnLoc = 1;
      int32_t nClassId = 0x3c;
      D2UnitStrc** ppPortalUnitOut = 0;
      eD2LevelId eLevel = LEVEL_Tristram;
      nStonesY += 4;
      nStonesX += 4;
      pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
      bIgnoreSpawnLoc = SKILLS::SkillsServer::SERVER_SpawnPortal(pGame, nullptr, pRoom, nStonesX, nStonesY, eLevel, ppPortalUnitOut, nClassId, bIgnoreSpawnLoc);
      if (bIgnoreSpawnLoc) {
        pDVar1->bPortalSpawned = 1;
        pDVar1->bExpansionPortalCheck = 0;
        return '\x01';
      }

      return '\0';
    }

    pDVar1->bExpansionPortalCheck = 0;
    return '\x01';
}

