// NOTE: this is A5Q3 (Prison of Ice / frozen Anya), not A1Q4 — co-located in the
// binary. Q33_UpdateFrozenAnyaNpcState: drives the frozen-Anya NPC animation state in
// Rogue Encampment (counts arrivals, flips to thawed anim once enough players present).
// No A1Q4 quest-state transitions.
void __fastcall Q33_UpdateFrozenAnyaNpcState(D2QuestDataStrc * pQuestData, D2UnitStrc * pUnit) {
    eD2MonsterAnimMode eUnitAnimMode;
    D2RoomStrc* pRoom;
    eD2LevelId eLevelId;
    int nPlayerArrivalCount;
    int32_t nTargetAnimMode;
    D2QuestDataA5Q3Strc* pA5Q3Specific;
    uint16_t* pnPlayerArrivalCount;
    if (!pUnit) {
      eUnitAnimMode = Death;
    } else {
      eUnitAnimMode = pUnit->eAnimMode.ePlayerMode;
    }

    switch (eUnitAnimMode) {
      case eD2MonsterAnimMode_ns::Neutral:
        {
          nTargetAnimMode = 2;
          break;
        }
      case Walk:
        {
          pA5Q3Specific = pQuestData->pQuestSpecificData.pA5Q3;
          pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
          eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
          if (eLevelId == LEVEL_RogueEncampment) {
            pnPlayerArrivalCount = &pA5Q3Specific->sQuestGUID.nPlayerCount;
            (*(int*)pnPlayerArrivalCount)++;
            nPlayerArrivalCount = (int)((uint32_t)(uint16_t)pA5Q3Specific->sQuestGUID.nPlayerCount | (uint32_t)(uint16_t)pA5Q3Specific->sQuestGUID.field2_0x82 << 16);
            if (nPlayerArrivalCount > 5) {
              pA5Q3Specific->bFrozensteinSpawned = 1;
            }
            if (!pA5Q3Specific->bFrozensteinSpawned) {
              goto schedule_next_update;
            }

            nTargetAnimMode = 3;
          } else {
            if (!pA5Q3Specific->bFrozenAnyaSpawned) {
              goto schedule_next_update;
            }

            nTargetAnimMode = 3;
          }

          break;
        }
      default:
        {
          goto schedule_next_update;
        }
      case eD2MonsterAnimMode_ns::GetHit:
        {
          nTargetAnimMode = 4;
          break;
        }
    }

    D2Common::Units::SetupUpdateFlag(pUnit, nTargetAnimMode);
    schedule_next_update:
    GAME::Event::SetEvent(pQuestData->pGame, pUnit, 7, pQuestData->pGame->dwGameFrame + 0x19, 0, 0);
}

// A1Q4 — Q04_GetCainPortalCoordinates: outputs the saved Cain-area portal coords
// (field 0xA8/0xAC) into pOutCoords if the quest is active, the portal-placed flag is
// set, and not suppressed. Returns 1 on success, 0 otherwise. Getter.
BOOL __thiscall Q04_GetCainPortalCoordinates(void * pThis, uint32_t * pOutCoords) {
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal((::SGAMEDATA*)pThis, QUESTINT_TheSearchForCain);
    if (pQuestData && pQuestData->bIsNotIntroduction != '\0') {
      D2QuestDataA1Q4Strc* pQuestSpecific;
      pQuestSpecific = pQuestData->pQuestSpecificData.pA1Q4;
      if (*(char*)((uintptr_t)&pQuestSpecific->sSub.field_0x7C + 2) != '\0' && !pQuestSpecific->sSub.field_0x7A) {
        *pOutCoords = pQuestSpecific->nPortalX;
        pOutCoords[1] = pQuestSpecific->nPortalY;
        return 1;
      }
    }

    return 0;
}

// A1Q4 — Q04_SpawnCainCage: spawns the Cain cage/gibbet object (object classId 0xbd)
// at the saved coords the first time (guarded by a one-shot flag), retrying nearby rooms
// and nudging the spawn position if no room is found. Records the cage GUID. No quest
// record transition.
BOOL __fastcall Q04_SpawnCainCage(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2QuestDataA1Q4Strc* pA1Q3Data;
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_TheSearchForCain);
    if (!pQuestData) {
      return 1;
    }

    D2QuestDataA1Q4Strc* pDVar2 = pQuestData->pQuestSpecificData.pA1Q4;
    if (*(char*)((uintptr_t)&pDVar2->sSub.field_0x7C + 1) != '\0') {
      return 1;
    }

    LONG nY = pDVar2->ptCainPos.y;
    D2RoomStrc* pSpawnRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    pSpawnRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pSpawnRoom, pDVar2->ptCainPos.x, nY);
    if (!pSpawnRoom) {
      pDVar2->ptCainPos.x += 3;
      pDVar2->ptCainPos.y += 3;
      return 1;
    }

    D2UnitStrc* pCageUnit = UNIT::SUnit::CreateUnit(UNIT_OBJECT, 0xbd, pDVar2->ptCainPos.x, pDVar2->ptCainPos.y, pGame, pSpawnRoom, 1, 1, nullptr);
    if (!pCageUnit) {
      return 1;
    }

    *(uint8_t*)((uintptr_t)&pDVar2->sSub.field_0x7C + 1) = 1;
    pDVar2->field_0x98 = pCageUnit->nUnitGUID;
    return 1;
}

// A1Q4 — Q04_GetCainPosition: outputs Cain's tile into pPoint — either the live unit
