// A1Q4 — Q04_InitializeTristramObjects: on Tristram load, re-creates the quest's
// persistent objects. Marks Tristram active, re-runs Objects_InitFn54 for the saved
// Cain unit, and (if the Cairn-stones unit is saved) re-creates the cage object (0xbd)
// near the stones, recording its GUID. Restores quest object state after zoning.
void __fastcall Q04_InitializeTristramObjects(::SGAMEDATA * pGame, D2UnitStrc * pUnit) {
    D2ObjectInitFnArg sInitArgGame;
    POINT sCairnPos;
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_TheSearchForCain);
    if (!pQuestData) {
      return;
    }

    D2QuestDataA1Q4Strc* pDVar1 = pQuestData->pQuestSpecificData.pA1Q4;
    pDVar1->sSub.bTristramInitialized = 1;
    pDVar1->sSub.bPendingCairnActivation = '\x01';
    if (pDVar1->sSub.bCairnObjectSaved != 1) {
      return;
    }

    D2UnitStrc* pFoundUnit = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_OBJECT, pDVar1->sSub.field_0x54);
    if (!pFoundUnit) {
      return;
    }

    sInitArgGame.pObject = pFoundUnit;
    sInitArgGame.pGame = pGame;
    sInitArgGame.pRoom = D2Common::Units::UNITS_GetRoom(pFoundUnit);
    sInitArgGame.nX = D2Client::Units::GetXPosFromDynamicPathUnit(pFoundUnit);
    sInitArgGame.nY = D2Client::Units::GetYPosFromDynamicPathUnit(pFoundUnit);
    Objects_InitFn54(&sInitArgGame);
    if (pDVar1->sSub.bCairnMonsterSaved != '\x01') {
      return;
    }

    pFoundUnit = UNIT::SUnit::FindUnitFromTable(pGame, UNIT_MONSTER, pDVar1->sSub.field_0x50);
    if (!pFoundUnit) {
      return;
    }

    D2Common::Units::GetCoords(pFoundUnit, &sCairnPos);
    LONG nCairnPosY = sCairnPos.y;
    D2RoomStrc* pCageRoom = D2Common::Units::UNITS_GetRoom(pFoundUnit);
    pCageRoom = D2Client::UNIT::Player::DRLGROOM_FindBetterNearbyRoom(pCageRoom, sCairnPos.x, nCairnPosY);
    if (!pCageRoom) {
      return;
    }

    pFoundUnit = UNIT::SUnit::CreateUnit(UNIT_OBJECT, 0xbd, sCairnPos.x, sCairnPos.y, pGame, pCageRoom, 1, 1, nullptr);
    if (!pFoundUnit) {
      return;
    }

    *(uint8_t*)((uintptr_t)&pDVar1->sSub.field_0x7C + 2) = 1;
    pDVar1->nCageObjectGUID = pFoundUnit->nUnitGUID;
}

